package com.discover.app.billing.domain; import com.discover.app.identity.domain.User; import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="invoice_cancellation_requests",indexes={@Index(name="idx_cancel_request_invoice_status",columnList="invoice_id,status"),@Index(name="idx_cancel_request_created",columnList="created_at")})
public class InvoiceCancellationRequest { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="invoice_id",nullable=false) private Invoice invoice; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private CancellationRequestStatus status=CancellationRequestStatus.DRAFT; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="requested_by_user_id",nullable=false) private User requestedBy; @Column(nullable=false) private LocalDateTime createdAt; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="decided_by_user_id") private User decidedBy; private LocalDateTime decidedAt; @Column(length=500) private String reason; protected InvoiceCancellationRequest(){} public InvoiceCancellationRequest(Invoice i,User u,String reason){invoice=i;requestedBy=u;this.reason=reason;createdAt=LocalDateTime.now();} public void approve(User admin){if(status!=CancellationRequestStatus.DRAFT)throw new IllegalStateException("Only draft cancellation requests can be approved.");invoice.cancel();status=CancellationRequestStatus.APPROVED;decidedBy=admin;decidedAt=LocalDateTime.now();} public void reject(User admin){if(status!=CancellationRequestStatus.DRAFT)throw new IllegalStateException("Only draft cancellation requests can be rejected.");status=CancellationRequestStatus.REJECTED;decidedBy=admin;decidedAt=LocalDateTime.now();} public Long getId(){return id;} public Invoice getInvoice(){return invoice;} public CancellationRequestStatus getStatus(){return status;} public User getRequestedBy(){return requestedBy;} public LocalDateTime getCreatedAt(){return createdAt;} public User getDecidedBy(){return decidedBy;} public LocalDateTime getDecidedAt(){return decidedAt;} public String getReason(){return reason;} }
